const now = new Date();
const vnNow = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' }));
const yesterday = new Date(vnNow);
yesterday.setDate(vnNow.getDate() - 1);

const yyyy = yesterday.getFullYear();
const mm = String(yesterday.getMonth() + 1).padStart(2, '0');
const dd = String(yesterday.getDate()).padStart(2, '0');
const yesterdayISO = `${yyyy}-${mm}-${dd}`;
const yesterdayVN = `${dd}/${mm}/${yyyy}`;

const todayHuman = `${String(vnNow.getDate()).padStart(2,'0')}/${String(vnNow.getMonth()+1).padStart(2,'0')}/${vnNow.getFullYear()}`;

return [{ json: { yesterdayISO, yesterdayVN, todayHuman } }];

// Tong hop dashboard cho ngay hom qua
const dateInfo = $('Tinh ngay hom qua').first().json;
const yesterdayISO = dateInfo.yesterdayISO;
const yesterdayVN = dateInfo.yesterdayVN;
const todayHuman = dateInfo.todayHuman;

// Sales: filter Ngay chot = yesterday
const salesAll = $('Get Sales (all)').all();
const salesYesterday = salesAll.filter(item => {
  const props = item.json.properties || {};
  const ngayChot = props['Ngày chốt']?.date?.start;
  return ngayChot && ngayChot.startsWith(yesterdayISO);
});

let tongDoanhThu = 0;
let tongDaThu = 0;
const salePerformance = { 'Bích': 0, 'Trân': 0, 'Ryan': 0 };
const productBreak = {};

for (const s of salesYesterday) {
  const p = s.json.properties;
  const giatri = p['Giá trị (VNĐ)']?.number || 0;
  const dathu = p['Đã thu (VNĐ)']?.number || 0;
  tongDoanhThu += giatri;
  tongDaThu += dathu;
  const sale = p['Sale']?.select?.name;
  if (sale && salePerformance[sale] !== undefined) salePerformance[sale] += giatri;
  const product = p['Sản phẩm/Khóa']?.select?.name;
  if (product) productBreak[product] = (productBreak[product] || 0) + giatri;
}

// Leads: filter Ngay tao = yesterday
const leadsAll = $input.all();
const leadsYesterday = leadsAll.filter(item => {
  const props = item.json.properties || {};
  const ngayTao = props['Ngày tạo']?.created_time;
  return ngayTao && ngayTao.startsWith(yesterdayISO);
});

const leadSources = {};
for (const l of leadsYesterday) {
  const src = l.json.properties['Nguồn']?.select?.name || 'Chưa rõ';
  leadSources[src] = (leadSources[src] || 0) + 1;
}

const formatVND = (n) => n.toLocaleString('vi-VN') + ' VNĐ';

let msg = `*📊 DRSKIN DASHBOARD — ${todayHuman}*\n`;
msg += `_Báo cáo ngày ${yesterdayVN}_\n\n`;

msg += `💰 *DOANH THU*\n`;
msg += `• Ký hợp đồng: *${formatVND(tongDoanhThu)}*\n`;
msg += `• Đã thu thực: *${formatVND(tongDaThu)}*\n`;
msg += `• Số deal: *${salesYesterday.length}*\n\n`;

if (Object.keys(productBreak).length > 0) {
  msg += `📦 *Theo sản phẩm:*\n`;
  for (const [prod, amt] of Object.entries(productBreak).sort((a,b)=>b[1]-a[1])) {
    msg += `  • ${prod}: ${formatVND(amt)}\n`;
  }
  msg += `\n`;
}

const saleEntries = Object.entries(salePerformance).filter(([s,amt]) => amt > 0);
if (saleEntries.length > 0) {
  msg += `👤 *Sale performance:*\n`;
  for (const [s, amt] of saleEntries) {
    msg += `  • ${s}: ${formatVND(amt)}\n`;
  }
  msg += `\n`;
}

msg += `🎯 *LEADS MỚI*\n`;
msg += `• Tổng: *${leadsYesterday.length}* lead\n`;
if (Object.keys(leadSources).length > 0) {
  for (const [src, n] of Object.entries(leadSources).sort((a,b)=>b[1]-a[1])) {
    msg += `  • ${src}: ${n}\n`;
  }
}

if (salesYesterday.length === 0 && leadsYesterday.length === 0) {
  msg += `\n⚠️ Không có data cho ngày này. Check Notion xem Bích/Trân đã nhập chưa.`;
}

msg += `\n\n🤖 _n8n auto-generated • ${new Date().toLocaleString('vi-VN', {timeZone:'Asia/Ho_Chi_Minh'})}_`;

return [{ json: { message: msg, salesCount: salesYesterday.length, leadsCount: leadsYesterday.length, totalRevenue: tongDoanhThu } }];
